mapper.select:
SELECT COUNT(*)
FROM education_achievements a
WHERE a.achievement_type = 'employment-rate-achievements' AND a.deleted_yn = 'N'
  AND a.teacher_user_id = #{teacherUserId} AND a.evaluation_year = #{evaluationYear}
  AND a.management_item_code = #{managementItemCode} AND a.achievement_date = #{achievementDate}
  AND COALESCE(a.achievement_name, '') = COALESCE(#{achievementName,jdbcType=VARCHAR}, '')
AND a.achievement_id != #{achievementId}

